contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 unusedParam) public payable {
        require(address(c).code.length > 0, "c must be deployed");
        require(c.sudicideAnyone.selector != bytes4(0), "selector must exist");

        bool firstReverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        bool secondReverted;
        c.sudicideAnyone(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        assert(!firstReverted || secondReverted);
    }

    receive() external payable {}
}

