// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 unusedParam) internal {
        vm.assume(address(c).code.length > 0);
        vm.assume(c.sudicideAnyone.selector != bytes4(0));
        bool firstReverted;
        try c.sudicideAnyone() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        bool secondReverted;
        try c.sudicideAnyone() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        assertTrue(!firstReverted || secondReverted);
    }

    function testFuzz_run(uint256 unusedParam) public {
        _run(unusedParam);
    }

    receive() external payable {}
}
